/**
 * CC2-02A — multi-cell regression against the actual new engine.
 *
 * These are not stand-in game states. They repeatedly select platform IDs
 * generated by the production candidate itself and drive its own ticks.
 */
import { describe, it, expect } from 'vitest';
import { CircuitClimbCore, replayCore } from '../core/CircuitClimbCore';

describe('CC2-02A: extended 20+ row deterministic gameplay', () => {
  it('completes 30 rows with regular wrong retries and bounded world history', () => {
    for (let seed = 0; seed < 30; seed += 1) {
      const core = new CircuitClimbCore('soak-' + seed);
      let previousValue: number | null = null;
      let badCount = 0;

      for (let index = 1; index <= 30; index += 1) {
        const before = core.snapshot();
        const problem = before.currentProblem;
        expect(problem.rowIndex).toBe(index);
        if (previousValue !== null && (index - 1) % 4 !== 0) {
          expect(problem.incomingValue).toBe(previousValue);
        }

        if (index % 5 === 0) {
          const wrong = problem.options.find(o => o.platformId !== problem.correctPlatformId)!;
          expect(core.selectPlatform(wrong.platformId)).toMatchObject({ ok: true, correct: false });
          core.advanceTicks(300);
          expect(core.snapshot().phase).toBe('ready');
          expect(core.snapshot().spark.value).toBe(problem.incomingValue);
          badCount += 1;
        }

        expect(core.selectPlatform(problem.correctPlatformId)).toMatchObject({ ok: true, correct: true });
        core.advanceTicks(300);
        const after = core.snapshot();
        expect(after.phase).toBe('ready');
        expect(after.completedRows).toBe(index);
        expect(after.solved.at(-1)?.result).toBe(problem.targetValue);
        expect(after.world.rows.length).toBeLessThanOrEqual(11);
        previousValue = problem.targetValue;
      }

      const final = core.snapshot();
      expect(final.completedRows).toBe(30);
      expect(final.wrongAttempts).toBe(badCount);
      expect(final.correctAttempts).toBe(30);
      expect(final.attempts).toBe(30 + badCount);
      expect(final.completedCells).toBe(7);
      expect(final.solved).toHaveLength(30);
      const events = core.eventLog();
      expect(events.filter(e => e.type === 'ROW_COMPLETED')).toHaveLength(30);
      expect(events.filter(e => e.type === 'VOLTAGE_REBASE')).toHaveLength(7);
      expect(events.filter(e => e.type === 'PLATFORM_SHORTED')).toHaveLength(badCount);
    }
  });

  it('exports and replays an actual 20-row mixed right/wrong run identically', () => {
    const core = new CircuitClimbCore('twenty-row-golden');
    for (let i = 0; i < 20; i += 1) {
      const problem = core.snapshot().currentProblem;
      if (i % 4 === 2) {
        const wrong = problem.options.find(o => o.platformId !== problem.correctPlatformId)!;
        core.selectPlatform(wrong.platformId);
        core.advanceTicks(300);
      }
      core.selectPlatform(problem.correctPlatformId);
      core.advanceTicks(300);
    }
    const replay = core.replayExport();
    const copy = replayCore(replay);
    expect(copy.snapshot()).toEqual(core.snapshot());
    expect(copy.eventLog()).toEqual(core.eventLog());
    expect(copy.stateDigest()).toBe(core.stateDigest());
  });
});
